/* { dg-options "-fsingle-precision-constant" } */
#include <stdio.h>

double global = 0.7;
static const double table[2] = {0.2, 1e-3};
static const double folded = 0.1 + 0.2;

int main(void) {
  double hex = 0x1.999999999999ap-4;
  double expo = 2.5e-1 * 3.3;
  printf("%.17g %.17g %.17g %.17g %.17g %.17g\n", global, table[0], table[1], folded, hex, expo);
  printf("%zu %zu %zu\n", sizeof(0.5), sizeof(0.5L), sizeof(0.5 + 1.0));

  double tenth = 0.1;
  double third = 1.0 / 3.0;
  long double exact = 0.1L;
  printf("%.17g %.17g %.17Lg\n", tenth, third, exact);
  printf("%d %d\n", tenth == 0.1f, sizeof(1.5) == sizeof(double));
  return 0;
}

